class Codec:
    def serialize(self, root):
        def r(node):
            if not node: return ['#']
            return [str(node.val)] + r(node.left) + r(node.right)
        return ','.join(r(root))

    def deserialize(self, data):
        vals = iter(data.split(','))
        def r():
            val = next(vals)
            if val == '#': return None
            node = TreeNode(int(val))
            node.left = r()
            node.right = r()
            return node
        return r()

