import heapq

class MedianFinder:
    def __init__(self):
        self.small = [] # max heap (invert signs)
        self.large = [] # min heap

    def addNum(self, num: int) -> None:
        heapq.heappush(self.small, -num)
        if self.small and self.large and (-self.small[0] > self.large[0]):
            val = -heapq.heappop(self.small)
            heapq.heappush(self.large, val)
        if len(self.small) > len(self.large) + 1:
            val = -heapq.heappop(self.small)
            heapq.heappush(self.large, val)
        if len(self.large) > len(self.small):
            val = heapq.heappop(self.large)
            heapq.heappush(self.small, -val)

    def findMedian(self) -> float:
        if len(self.small) > len(self.large):
            return float(-self.small[0])
        return (-self.small[0] + self.large[0]) / 2.0

templates.javascript:
var MedianFinder = function() {
    this.arr = [];
};

MedianFinder.prototype.addNum = function(num) {
    let low = 0, high = this.arr.length;
    while (low < high) {
        let mid = (low + high) >> 1;
        if (this.arr[mid] < num) low = mid + 1;
        else high = mid;
    }
    this.arr.splice(low, 0, num);
};

MedianFinder.prototype.findMedian = function() {
    const n = this.arr.length;
    if (n % 2 === 1) return this.arr[Math.floor(n / 2)];
    return (this.arr[n / 2 - 1] + this.arr[n / 2]) / 2;
};

templates.java:
class MedianFinder {
    private PriorityQueue<Integer> small = new PriorityQueue<>(Collections.reverseOrder());
    private PriorityQueue<Integer> large = new PriorityQueue<>();

    public MedianFinder() {}

    public void addNum(int num) {
        small.offer(num);
        large.offer(small.poll());
        if (small.size() < large.size()) {
            small.offer(large.poll());
        }
    }

    public double findMedian() {
        return small.size() > large.size() ? small.peek() : (small.peek() + large.peek()) / 2.0;
    }
}

templates.c_cpp:
#include <queue>
using namespace std;

class MedianFinder {
    priority_queue<int> small; // max heap
    priority_queue<int, vector<int>, greater<int>> large; // min heap
public:
    MedianFinder() {}
    void addNum(int num) {
        small.push(num);
        large.push(small.top());
        small.pop();
        if (small.size() < large.size()) {
            small.push(large.top());
            large.pop();
        }
    }
    double findMedian() {
        return small.size() > large.size() ? small.top() : (small.top() + large.top()) / 2.0;
    }
};

