templates.python:
class WordDictionary:
    def __init__(self):
        self.trie = {}

    def addWord(self, word: str) -> None:
        curr = self.trie
        for c in word:
            if c not in curr: curr[c] = {}
            curr = curr[c]
        curr['$'] = True

    def search(self, word: str) -> bool:
        def dfs(node, idx):
            if idx == len(word): return '$' in node
            c = word[idx]
            if c == '.':
                for k in node:
                    if k != '$' and dfs(node[k], idx + 1): return True
                return False
            if c not in node: return False
            return dfs(node[c], idx + 1)
        return dfs(self.trie, 0)

templates.javascript:
var WordDictionary = function() {
    this.trie = {};
};

WordDictionary.prototype.addWord = function(word) {
    let node = this.trie;
    for (let c of word) {
        if (!node[c]) node[c] = {};
        node = node[c];
    }
    node.isWord = true;
};

WordDictionary.prototype.search = function(word) {
    function dfs(node, idx) {
        if (idx === word.length) return !!node.isWord;
        const c = word[idx];
        if (c === '.') {
            for (let k of Object.keys(node)) {
                if (k !== 'isWord' && dfs(node[k], idx + 1)) return true;
            }
            return false;
        }
        if (!node[c]) return false;
        return dfs(node[c], idx + 1);
    }
    return dfs(this.trie, 0);
};

templates.java:
class WordDictionary {
    private class Node {
        Node[] children = new Node[26];
        boolean isWord = false;
    }
    private Node root = new Node();

    public WordDictionary() {}

    public void addWord(String word) {
        Node curr = root;
        for (char c : word.toCharArray()) {
            if (curr.children[c - 'a'] == null) curr.children[c - 'a'] = new Node();
            curr = curr.children[c - 'a'];
        }
        curr.isWord = true;
    }

    public boolean search(String word) {
        return dfs(word, 0, root);
    }

    private boolean dfs(String word, int idx, Node node) {
        if (node == null) return false;
        if (idx == word.length()) return node.isWord;
        char c = word.charAt(idx);
        if (c == '.') {
            for (Node child : node.children) {
                if (child != null && dfs(word, idx + 1, child)) return true;
            }
            return false;
        }
        return dfs(word, idx + 1, node.children[c - 'a']);
    }
}

templates.c_cpp:
class WordDictionary {
    struct Node {
        Node* children[26] = {};
        bool isWord = false;
    } *root;
public:
    WordDictionary() { root = new Node(); }
    void addWord(string word) {
        Node* curr = root;
        for (char c : word) {
            if (!curr->children[c - 'a']) curr->children[c - 'a'] = new Node();
            curr = curr->children[c - 'a'];
        }
        curr->isWord = true;
    }
    bool search(string word) { return dfs(word, 0, root); }
    bool dfs(const string& word, int idx, Node* node) {
        if (!node) return false;
        if (idx == word.size()) return node->isWord;
        char c = word[idx];
        if (c == '.') {
            for (int i = 0; i < 26; i++) {
                if (node->children[i] && dfs(word, idx + 1, node->children[i])) return true;
            }
            return false;
        }
        return dfs(word, idx + 1, node->children[c - 'a']);
    }
};

